@Service
public class RoutingService 
		extends BaseService {
//************************************************************************
// Public Methods
//************************************************************************
	/**
	 * Default Constructor
	 */
    public RoutingService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new RoutingEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(RoutingRepository.class) );
		this.validator		= applicationContext.getBean(RoutingValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Routing
	 */
		public Routing createRouting( CreateRoutingCommand command ) {

		Routing entity = new Routing();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setRoutingId( command.getRoutingId() );
            entity.setRoutingNumber( command.getRoutingNumber() );
            entity.setRevision( command.getRevision() );
            entity.setEffectivityStart( command.getEffectivityStart() );
            entity.setEffectivityEnd( command.getEffectivityEnd() );
            entity.setRoutingType( command.getRoutingType() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Routing {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateRoutingCommand
	 * @return		Routing
	 */
	public Routing updateRouting( UpdateRoutingCommand command ) {

		Routing entity = new Routing();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setRoutingId( command.getRoutingId() );
            entity.setRoutingNumber( command.getRoutingNumber() );
            entity.setRevision( command.getRevision() );
            entity.setEffectivityStart( command.getEffectivityStart() );
            entity.setEffectivityEnd( command.getEffectivityEnd() );
            entity.setItem( command.getItem() );
            entity.setOperations( command.getOperations() );
            entity.setRoutingType( command.getRoutingType() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Routing {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteRoutingCommand
	 */
	public void delete( DeleteRoutingCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getRoutingId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Routing {0} ", id );

	}

	/**
	 * Method to retrieve the Routing via RoutingFetchOneSummary
	 * @param 	summary RoutingFetchOneSummary
	 * @return 	RoutingFetchOneResponse
	 */
	public Routing getRouting( RoutingFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "RoutingFetchOneSummary arg cannot be null" );

		Routing entity = null;
		UUID id = summary.getRoutingId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Routing using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Routings
	 *
	 * @return 	List<Routing>
	 */
    public List<Routing> getAllRouting() {
		List<Routing> list = projector.findAll( new FindAllRoutingQuery() );
		return list;
	}

	/**
	 * assign Item on Routing
	 * @param		command AssignItemToRoutingCommand
	 */
	public void assignItem( AssignItemToRoutingCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignItem(command.getRoutingId(), command.getAssignment());

	}

	/**
	 * unAssign Item on Routing
	 * @param		command UnAssignItemFromRoutingCommand
	 */
	public void unAssignItem( UnAssignItemFromRoutingCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.unAssignItem(command.getRoutingId());
	}
	

	/**
	 * add Operation to Operations
	 * @param		command AssignOperationsToRoutingCommand
	 */
	public void addToOperations( AssignOperationsToRoutingCommand command ) {

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.addToOperations(command.getRoutingId(), command.getAddTo());
	}

	/**
	 * remove Operation from Operations
	 * @param		command RemoveOperationsFromRoutingCommand
	 */
	public void removeFromOperations( RemoveOperationsFromRoutingCommand command )  {
		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.removeFromOperations(command.getRoutingId(), command.getRemoveFrom());
	}




//************************************************************************
// Attributes
//************************************************************************
	@Autowired
    private final RoutingEntityProjector projector;
	private final RoutingValidator validator;
	private Routing routing 	= null;
	private CurrentIdentity identity			= null;
	private static final Logger LOGGER 			=  LoggerFactory.getLogger(RoutingService.class);
}
